insert into public.training_blocks (id, number, name, method, start_date, weeks, origin, summary) values ('block-2027-02-08-hypertrophy-reverse-pyramid-iii', 9, 'Hypertrophy Reverse Pyramid III', 'reverse-pyramid', '2027-02-08', 6, 'pt', 'Reverse pyramids and drop sets after the ascending-pyramid block, as the coach followed block 4 with block 5: heaviest set first (8-10-12-15 on A, 10-12-15-20 on B, load drops each set), drop sets of 12+12 (A) / 15+15 (B), and a straight finisher. Flat barbell bench and front squats replace the coach''s incline bench and hack squat.') on conflict (id) do update set number = excluded.number, name = excluded.name, method = excluded.method, start_date = excluded.start_date, weeks = excluded.weeks, origin = excluded.origin, summary = excluded.summary, updated_at = now();
